class Provider implements CustomSource {
    base_url = "https://www.pornhub.com"

    getSettings(): Settings {
        return {
            supportsAnime: true,
            supportsManga: false,
        }
    }

    async getAnime(ids: number[]): Promise<$app.AL_BaseAnime[]> {
        const ret: $app.AL_BaseAnime[] = []
        const cache = this._getMediaCache()

        for (const id of ids) {
            const cached = cache[id]
            if (cached?.media) {
                ret.push(cached.media)
            }
        }

        return ret
    }

    async getAnimeDetails(id: number): Promise<$app.AL_AnimeDetailsById_Media | null> {
        return null
    }

    async getAnimeMetadata(id: number): Promise<$app.Metadata_AnimeMetadata | null> {
        const cache = this._getMediaCache()
        return cache[id]?.metadata ?? null
    }

    async getAnimeWithRelations(id: number): Promise<$app.AL_CompleteAnime> {
        const cache = this._getMediaCache()
        const cached = cache[id]

        if (!cached?.media) {
            throw new Error("not found.")
        }

        return {
            ...(cached.media as any),
            relations: { edges: [] },
        } as $app.AL_CompleteAnime
    }

    async listAnime(search: string, page: number, perPage: number): Promise<ListResponse<$app.AL_BaseAnime>> {
        const query = String(search || "").trim()
        const currentPage = page && page > 0 ? page : 1
        const limit = Math.max(1, Math.min(perPage || 20, 50))

        let videos: PornhubVideo[] = []

        if (query.length > 0) {
            const directId = this._getPornhubId(query)

            if (directId) {
                const video = await this._getVideoFromPage(this._watchUrl(directId))
                videos = video ? [video] : []
            } else {
                videos = await this._searchVideos(query, currentPage)
            }
        } else {
            videos = await this._getPopularVideos(currentPage)
        }

        videos = this._dedupeVideos(videos)
            .filter(v => v && v.videoId && v.title)
            .slice(0, limit)

        const cache = this._getMediaCache()
        const media: $app.AL_BaseAnime[] = []

        for (const video of videos) {
            const stored = this._videoToStoredMedia(video)
            cache[stored.media.id] = stored
            media.push(stored.media)
        }

        this._setMediaCache(cache)

        return {
            media,
            total: query.length > 0 ? Math.max(media.length, currentPage * limit + media.length) : media.length,
            page: currentPage,
            totalPages: media.length >= limit ? currentPage + 1 : Math.max(1, currentPage),
        }
    }

    async getManga(ids: number[]): Promise<$app.AL_BaseManga[]> {
        return []
