    private async _searchVideos(query: string, page: number): Promise<PornhubVideo[]> {
        const urls = [
            `${this._baseUrl()}/video/search?search=${encodeURIComponent(query)}&page=${encodeURIComponent(String(page || 1))}`,
            `${this._baseUrl()}/video/search?search=${encodeURIComponent(query)}`,
        ]

        for (const url of urls) {
            try {
                console.log("Pornhub source search:", url)

                const html = await this._fetchText(url)

                if (!html || html.length < 500) {
                    continue
                }

                const videos = this._parseSearchPage(html)

                if (videos.length > 0) {
                    return videos
                }
            } catch (err) {
                console.error("Pornhub search error:", err)
            }
        }

        return []
    }

    private async _getPopularVideos(page: number): Promise<PornhubVideo[]> {
        const urls = [
            `${this._baseUrl()}/video?o=ht&page=${encodeURIComponent(String(page || 1))}`,
            `${this._baseUrl()}/video?o=mv&page=${encodeURIComponent(String(page || 1))}`,
            `${this._baseUrl()}/video`,
        ]

        for (const url of urls) {
            try {
                console.log("Pornhub popular:", url)

                const html = await this._fetchText(url)

                if (!html || html.length < 500) {
                    continue
                }

                const videos = this._parseSearchPage(html)

                if (videos.length > 0) {
                    return videos
                }
            } catch (err) {
                console.error("Pornhub popular error:", err)
            }
        }

        return []
    }

    private async _getVideoFromPage(url: string): Promise<PornhubVideo | null> {
        try {
            const html = await this._fetchText(url)

            if (!html || html.length < 500) {
                return null
            }

            const jsonLdVideo = this._parseJsonLdVideo(html, url)

            if (jsonLdVideo) {
                return jsonLdVideo
            }

            const title =
                this._decode(this._match(html, /<meta\s+property=["']og:title["']\s+content=["']([^"']+)["']/i)) ||
                this._decode(this._match(html, /<title[^>]*>([\s\S]*?)<\/title>/i)) ||
                "Pornhub Video"

            const image =
                this._decode(this._match(html, /<meta\s+property=["']og:image["']\s+content=["']([^"']+)["']/i)) ||
                ""

            const videoId = this._getPornhubId(url) || this._numericId(url).toString()

            return {
                videoId,
                title,
                url,
                thumbnail: image,
                author: "Pornhub",
                durationSeconds: 0,
                views: 0,
                publishedText: "",
                description: "",
            }
        } catch (err) {
            console.error("Pornhub video page error:", err)
            return null
        }
    }

    private _parseSearchPage(html: string): PornhubVideo[] {
        const videos: PornhubVideo[] = []

        const jsonLdVideos = this._parseJsonLdList(html)

        if (jsonLdVideos.length > 0) {
            videos.push(...jsonLdVideos)
        }

        const patterns = [
            /<a[^>]+href=["']([^"']*view_video\.php\?viewkey=[^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi,
            /<a[^>]+href=["']([^"']*\/view_video\.php\?viewkey=[^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi,
        ]

        for (const pattern of patterns) {
            let match: RegExpExecArray | null

            while ((match = pattern.exec(html)) !== null) {
                const rawHref = this._decode(match[1] || "")
                const inner = match[2] || ""
                const videoId = this._getPornhubId(rawHref)

                if (!videoId) {
                    continue
                }

                const title =
                    this._decode(this._match(inner, /title=["']([^"']+)["']/i)) ||
                    this._decode(this._match(inner, /alt=["']([^"']+)["']/i)) ||
                    this._decode(this._stripTags(inner)).trim()

                if (!title || title.length < 2) {
                    continue
                }

                const thumb =
                    this._decode(this._match(inner, /data-mediumthumb=["']([^"']+)["']/i)) ||
                    this._decode(this._match(inner, /data-src=["']([^"']+)["']/i)) ||
                    this._decode(this._match(inner, /src=["']([^"']+)["']/i)) ||
                    ""

                videos.push({
                    videoId,
                    title,
                    url: this._normalizeUrl(rawHref),
                    thumbnail: this._normalizeUrl(thumb),
                    author: "Pornhub",
                    durationSeconds: 0,
                    views: 0,
                    publishedText: "",
                    description: "",
                })
            }
        }

        const dataVideoPattern = /viewkey=([a-zA-Z0-9_-]+)[\s\S]{0,1200}?(?:title|alt)=["']([^"']+)["']/gi
        let match: RegExpExecArray | null

        while ((match = dataVideoPattern.exec(html)) !== null) {
            const videoId = match[1]
            const title = this._decode(match[2] || "")

            if (!videoId || !title) {
                continue
            }

            videos.push({
                videoId,
                title,
                url: this._watchUrl(videoId),
                thumbnail: this._findNearbyThumbnail(html, dataVideoPattern.lastIndex),
                author: "Pornhub",
                durationSeconds: 0,
                views: 0,
                publishedText: "",
                description: "",
            })
        }

        return this._dedupeVideos(videos)
    }

    private _parseJsonLdList(html: string): PornhubVideo[] {
        const ret: PornhubVideo[] = []
        const scripts = this._extractScriptJsonLd(html)

        for (const raw of scripts) {
            try {
                const data = JSON.parse(raw)
                const items = this._flattenJsonLd(data)

                for (const item of items) {
                    const video = this._jsonLdToVideo(item, "")
                    if (video) {
                        ret.push(video)
                    }
                }
            } catch (err) {
            }
        }

        return ret
    }

    private _parseJsonLdVideo(html: string, pageUrl: string): PornhubVideo | null {
        const scripts = this._extractScriptJsonLd(html)

        for (const raw of scripts) {
            try {
                const data = JSON.parse(raw)
                const items = this._flattenJsonLd(data)

                for (const item of items) {
                    const video = this._jsonLdToVideo(item, pageUrl)
                    if (video) {
                        return video
                    }
                }
            } catch (err) {
            }
        }

        return null
    }

    private _jsonLdToVideo(item: any, fallbackUrl: string): PornhubVideo | null {
        if (!item) return null

        const type = String(item["@type"] || item.type || "").toLowerCase()

        if (type && !type.includes("videoobject") && !type.includes("video")) {
            return null
        }

        const name = item.name || item.title || ""
        const url = item.url || item.contentUrl || item.embedUrl || fallbackUrl || ""

        const videoId = this._getPornhubId(url) || this._getPornhubId(item["@id"] || "")

        if (!videoId || !name) {
            return null
        }

        const thumbnail = Array.isArray(item.thumbnailUrl)
            ? item.thumbnailUrl[0]
            : item.thumbnailUrl || item.thumbnail || ""

        const durationSeconds = this._parseIsoDuration(item.duration || "")

        return {
            videoId,
            title: this._decode(name),
            url: this._normalizeUrl(url || this._watchUrl(videoId)),
            thumbnail: this._normalizeUrl(String(thumbnail || "")),
            author: this._jsonLdAuthor(item),
            durationSeconds,
            views: 0,
            publishedText: item.uploadDate || item.datePublished || "",
            description: this._decode(item.description || ""),
        }
    }

    private _videoToStoredMedia(video: PornhubVideo): StoredPornhubMedia {
        const videoId = video.videoId
        const id = this._numericId(videoId)

        const title = this._decode(video.title || "Pornhub Video")
        const author = this._decode(video.author || "Pornhub")
        const thumb = this._normalizeUrl(video.thumbnail || "")

        const publishedDate = this._parseDate(video.publishedText)
        const airDate = publishedDate
            ? `${publishedDate.year}-${this._pad(publishedDate.month || 1)}-${this._pad(publishedDate.day || 1)}`
            : ""

        const lengthMinutes = video.durationSeconds
            ? Math.max(1, Math.round(video.durationSeconds / 60))
            : 0

        const description = this._truncate(
            [
                `Source: Pornhub`,
                `Channel: ${author}`,
                "",
                this._decode(video.description || ""),
                "",
                `Open page: ${video.url || this._watchUrl(videoId)}`,
            ].filter(Boolean).join("\n"),
            2500,
        )

        const media: $app.AL_BaseAnime = {
            id,
            siteUrl: video.url || this._watchUrl(videoId),
            title: {
                userPreferred: title,
                romaji: title,
                english: title,
                native: title,
            },
            coverImage: {
                large: thumb,
                medium: thumb,
                extraLarge: thumb,
                color: "",
            },
            bannerImage: thumb,
            description,
            genres: ["Adult", "Pornhub", author],
            meanScore: 0,
            synonyms: [videoId, author],
            status: "FINISHED",
            episodes: 1,
            type: "ANIME",
            format: "ONA",
            seasonYear: publishedDate?.year || new Date().getUTCFullYear(),
            isAdult: true,
            startDate: publishedDate || {
                year: new Date().getUTCFullYear(),
            },
            endDate: publishedDate || undefined,
        }

        const metadata: $app.Metadata_AnimeMetadata = {
            titles: {
                en: title,
            },
            episodes: {
                "1": {
                    anidbId: 0,
                    tvdbId: 0,
                    anidbEid: 0,
                    title,
                    image: thumb,
                    airDate,
                    length: lengthMinutes,
                    summary: description,
                    overview: description,
                    episodeNumber: 1,
                    episode: "1",
                    seasonNumber: 1,
                    absoluteEpisodeNumber: 1,
                    hasImage: !!thumb,
                },
            },
            episodeCount: 1,
            specialCount: 0,
        }

        return {
            videoId,
            media,
            metadata,
        }
    }

    private async _fetchText(url: string): Promise<string> {
        const res = await fetch(url, {
            headers: {
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
                "Accept-Language": "en-US,en;q=0.9",
                "User-Agent": "Mozilla/5.0",
            },
        })

        if (!res.ok) {
            throw new Error(`HTTP ${res.status} for ${url}`)
        }

        return await res.text()
    }

    private _extractScriptJsonLd(html: string): string[] {
        const ret: string[] = []
        const pattern = /<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi
        let match: RegExpExecArray | null

        while ((match = pattern.exec(html)) !== null) {
            const raw = (match[1] || "").trim()
            if (raw) {
                ret.push(raw)
            }
        }

        return ret
    }

    private _flattenJsonLd(data: any): any[] {
        const ret: any[] = []

        const walk = (value: any) => {
            if (!value) return

            if (Array.isArray(value)) {
                for (const item of value) {
                    walk(item)
                }
                return
            }

            if (typeof value === "object") {
                ret.push(value)

                if (Array.isArray(value["@graph"])) {
                    walk(value["@graph"])
                }

                if (Array.isArray(value.itemListElement)) {
                    for (const el of value.itemListElement) {
                        if (el?.item) {
                            walk(el.item)
                        } else {
                            walk(el)
                        }
                    }
                }
            }
        }

        walk(data)
        return ret
    }

    private _jsonLdAuthor(item: any): string {
        const author = item.author || item.creator || item.publisher

        if (!author) return "Pornhub"

        if (typeof author === "string") return author

        if (Array.isArray(author)) {
            for (const a of author) {
                if (typeof a === "string") return a
                if (a?.name) return a.name
            }
        }

        if (author.name) return author.name

        return "Pornhub"
    }

    private _findNearbyThumbnail(html: string, index: number): string {
        const start = Math.max(0, index - 1200)
        const end = Math.min(html.length, index + 1200)
        const chunk = html.slice(start, end)

        const thumb =
            this._match(chunk, /data-mediumthumb=["']([^"']+)["']/i) ||
            this._match(chunk, /data-src=["']([^"']+)["']/i) ||
            this._match(chunk, /src=["']([^"']+)["']/i) ||
            ""

        return this._normalizeUrl(this._decode(thumb))
    }

    private _getPornhubId(input: string): string {
        const text = String(input || "").trim()

        const patterns = [
            /viewkey=([a-zA-Z0-9_-]+)/i,
            /\/view_video\.php\?viewkey=([a-zA-Z0-9_-]+)/i,
        ]

        for (const pattern of patterns) {
            const match = text.match(pattern)
            if (match?.[1]) return match[1]
        }

        if (/^[a-zA-Z0-9_-]{8,}$/.test(text)) {
            return text
        }

        return ""
    }

    private _watchUrl(videoId: string): string {
        return `${this._baseUrl()}/view_video.php?viewkey=${encodeURIComponent(videoId)}`
    }

    private _baseUrl(): string {
        let url = this.base_url || "https://www.pornhub.com"

        if (url.includes("{{") || url.includes("}}")) {
            url = "https://www.pornhub.com"
        }

        return this._trimSlash(url)
    }

    private _normalizeUrl(url: string): string {
        if (!url) return ""

        if (url.startsWith("//")) {
            return "https:" + url
        }

        if (url.startsWith("/")) {
            return this._baseUrl() + url
        }

        return url
    }

    private _match(text: string, pattern: RegExp): string {
        const match = String(text || "").match(pattern)
        return match?.[1] || ""
    }

    private _stripTags(input: string): string {
        return String(input || "")
            .replace(/<script[\s\S]*?<\/script>/gi, "")
            .replace(/<style[\s\S]*?<\/style>/gi, "")
            .replace(/<[^>]+>/g, " ")
            .replace(/\s+/g, " ")
            .trim()
    }

    private _decode(input: string): string {
        return String(input || "")
            .replace(/&amp;/g, "&")
            .replace(/&quot;/g, "\"")
            .replace(/&#39;/g, "'")
            .replace(/&apos;/g, "'")
            .replace(/&lt;/g, "<")
            .replace(/&gt;/g, ">")
            .replace(/&#x2F;/g, "/")
            .replace(/&#47;/g, "/")
    }

    private _truncate(input: string, max: number): string {
        if (!input) return ""
        if (input.length <= max) return input
        return input.slice(0, max - 3) + "..."
    }

    private _parseDate(input?: string): { year: number, month?: number, day?: number } | null {
        if (!input) return null

        const d = new Date(input)

        if (isNaN(d.getTime())) {
            return null
        }

        return {
            year: d.getUTCFullYear(),
            month: d.getUTCMonth() + 1,
            day: d.getUTCDate(),
        }
    }

    private _parseIsoDuration(input: string): number {
        const text = String(input || "")

        const match = text.match(/P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/i)

        if (!match) return 0

        const days = Number(match[1] || 0)
        const hours = Number(match[2] || 0)
        const minutes = Number(match[3] || 0)
        const seconds = Number(match[4] || 0)

        return days * 86400 + hours * 3600 + minutes * 60 + seconds
    }

    private _numericId(input: string): number {
        let hash = 2166136261
        const value = String(input || "")

        for (let i = 0; i < value.length; i++) {
            hash ^= value.charCodeAt(i)
            hash = Math.imul(hash, 16777619)
        }

        return Math.abs(hash) + 1
    }

    private _trimSlash(input: string): string {
        let value = String(input || "").trim()

        while (value.endsWith("/")) {
            value = value.slice(0, -1)
        }

        return value
    }

    private _dedupeVideos(videos: PornhubVideo[]): PornhubVideo[] {
        const seen: Record<string, boolean> = {}
        const ret: PornhubVideo[] = []

        for (const video of videos) {
            if (!video?.videoId || seen[video.videoId]) {
                continue
            }

            seen[video.videoId] = true
            ret.push(video)
        }

        return ret
    }

    private _pad(value: number): string {
        return value < 10 ? `0${value}` : `${value}`
    }

    private _getMediaCache(): Record<number, StoredPornhubMedia> {
        return ($store.get("pornhub.media") as Record<number, StoredPornhubMedia> | undefined) || {}
    }

    private _setMediaCache(cache: Record<number, StoredPornhubMedia>) {
        $store.set("pornhub.media", cache)
    }
}

type StoredPornhubMedia = {
    videoId: string
    media: $app.AL_BaseAnime
    metadata: $app.Metadata_AnimeMetadata
}

type PornhubVideo = {
    videoId: string
    title: string
    url: string
    thumbnail: string
    author?: string
    durationSeconds?: number
    views?: number
    publishedText?: string
    description?: string
}
